select date_trunc('year', last_restock) as year_start, product_id, approx_percentile(quantity, 0.5) as quantity_p50, percentile_approx(quantity, array(0.25, 0.5, 0.75)) as quantity_quartiles, round(avg(quantity), 2) as avg_quantity, grouping(date_trunc('year', last_restock)) as gid from inventory group by rollup (date_trunc('year', last_restock), product_id) order by quantity_p50 asc
